#!/usr/bin/env node
// Copies the WordPress plugin (wordpress-plugin/plazo) into src/wordpress/plugin-files.generated.ts, which the API zips
// when a parking downloads it (19/11/2026). `--check` fails when the generated file is out of date (CI).
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = fileURLToPath(new URL('.', import.meta.url));
const root = join(here, '..', '..', 'wordpress-plugin', 'plazo');
const target = join(here, '..', 'src', 'wordpress', 'plugin-files.generated.ts');

const files = [];
const walk = dir => {
  for (const name of readdirSync(dir).sort()) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) walk(path);
    else files.push([relative(root, path).split(sep).join('/'), readFileSync(path, 'utf8')]);
  }
};
walk(root);
const body =
  '// Generated by tools/sync-wordpress-plugin.mjs from wordpress-plugin/plazo: do not edit by hand.\n' +
  `export const PLUGIN_FILES: Record<string, string> = ${JSON.stringify(Object.fromEntries(files), null, 2)};\n`;
if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {}
  if (current !== body) {
    console.error('src/wordpress/plugin-files.generated.ts is out of date: run node tools/sync-wordpress-plugin.mjs');
    process.exit(1);
  }
} else {
  writeFileSync(target, body);
  console.log(`${files.length} files written to ${relative(process.cwd(), target)}`);
}
